-- =============================================================
-- Create furnished_offices table
-- =============================================================
CREATE TABLE IF NOT EXISTS `furnished_offices` (
  `id`              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `title`           VARCHAR(255) NOT NULL,
  `slug`            VARCHAR(255) NOT NULL UNIQUE,
  `listing_type`    VARCHAR(50)  NULL,
  `description`     TEXT         NULL,
  `city`            VARCHAR(100) NULL,
  `area`            VARCHAR(255) NULL,
  `address`         TEXT         NULL,
  `latitude`        DOUBLE       NULL,
  `longitude`       DOUBLE       NULL,
  `price`           DOUBLE       NULL,
  `price_label`     VARCHAR(100) NULL,
  `total_seats`     INT UNSIGNED NULL,
  `available_sqft`  VARCHAR(100) NULL,
  `min_inventory`   VARCHAR(50)  NULL,
  `inventory_type`  VARCHAR(100) NULL,
  `total_area_sqft` INT UNSIGNED NOT NULL DEFAULT 0,
  `office_space_type` VARCHAR(20) NOT NULL DEFAULT 'rent',
  `amenities`       JSON         NULL,
  `images`          JSON         NULL,
  `feature_highlights` JSON         NULL,
  `featured`        TINYINT(1)   NOT NULL DEFAULT 0,
  `seo_text`        TEXT         NULL,
  `status`          VARCHAR(20)  NOT NULL DEFAULT 'draft',
  `listing_code`    VARCHAR(20)  NULL,
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================
-- Create unfurnished_offices table
-- =============================================================
CREATE TABLE IF NOT EXISTS `unfurnished_offices` (
  `id`              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `title`           VARCHAR(255) NOT NULL,
  `slug`            VARCHAR(255) NOT NULL UNIQUE,
  `listing_type`    VARCHAR(50)  NULL,
  `description`     TEXT         NULL,
  `city`            VARCHAR(100) NULL,
  `area`            VARCHAR(255) NULL,
  `address`         TEXT         NULL,
  `latitude`        DOUBLE       NULL,
  `longitude`       DOUBLE       NULL,
  `price`           DOUBLE       NULL,
  `price_label`     VARCHAR(100) NULL,
  `total_seats`     INT UNSIGNED NULL,
  `available_sqft`  VARCHAR(100) NULL,
  `min_inventory`   VARCHAR(50)  NULL,
  `inventory_type`  VARCHAR(100) NULL,
  `total_area_sqft` INT UNSIGNED NOT NULL DEFAULT 0,
  `office_space_type` VARCHAR(20) NOT NULL DEFAULT 'rent',
  `amenities`       JSON         NULL,
  `images`          JSON         NULL,
  `feature_highlights` JSON         NULL,
  `featured`        TINYINT(1)   NOT NULL DEFAULT 0,
  `seo_text`        TEXT         NULL,
  `status`          VARCHAR(20)  NOT NULL DEFAULT 'draft',
  `listing_code`    VARCHAR(20)  NULL,
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Indexes for furnished_offices
CREATE INDEX idx_furnished_status ON furnished_offices(status);
CREATE INDEX idx_furnished_city ON furnished_offices(city);
CREATE INDEX idx_furnished_area ON furnished_offices(area);
CREATE INDEX idx_furnished_slug ON furnished_offices(slug);
CREATE INDEX idx_furnished_featured ON furnished_offices(featured, status);
CREATE INDEX idx_furnished_created ON furnished_offices(created_at);
CREATE INDEX idx_furnished_price ON furnished_offices(price);
CREATE INDEX idx_furnished_seats ON furnished_offices(total_seats);

-- Indexes for unfurnished_offices
CREATE INDEX idx_unfurnished_status ON unfurnished_offices(status);
