CREATE INDEX idx_unfurnished_featured ON unfurnished_offices(featured, status);
CREATE INDEX idx_unfurnished_created ON unfurnished_offices(created_at);
CREATE INDEX idx_unfurnished_price ON unfurnished_offices(price);
CREATE INDEX idx_unfurnished_seats ON unfurnished_offices(total_seats);

